def extract_patches(
    data: np.ndarray,                 # Input array (n-dimensional)
    patch_size: tuple,                # Patch size per dimension
    overlap: float | tuple,           # Overlap fraction(s)
    transforms: List[Callable]|None = None # Optional list of transforms
):
    """
    Extract n-dimensional patches from input data.
    Optionally applies transforms to the full data before extracting patches.

    Parameters
    ----------
    data : np.ndarray
    patch_size : tuple
    overlap : float or tuple
    transforms : list of callables, optional
        Each transform must take a np.ndarray and return a np.ndarray
        of the same dimensionality.

    Returns
    -------
    patches : list of np.ndarray
    """

    def _extract_from_single_array(arr: np.ndarray):
        data_shape = arr.shape
        ndim = len(patch_size)

        # normalize overlap
        if isinstance(overlap, (int, float)):
            overlap_tuple = (overlap,) * ndim
        else:
            if len(overlap) != ndim:
                raise ValueError("overlap tuple must match patch dimensions")
            overlap_tuple = overlap

        # compute strides (>=1)
        strides = tuple(
            max(1, int(patch_size[i] * (1 - overlap_tuple[i])))
            for i in range(ndim)
        )

        # compute start indices
        slices = [
            range(0, data_shape[i] - patch_size[i] + 1, strides[i])
            for i in range(ndim)
        ]

        patches_local = []

        for indices in np.ndindex(*[len(s) for s in slices]):
            patch_slices = tuple(
                slice(slices[dim][idx], slices[dim][idx] + patch_size[dim])
                for dim, idx in enumerate(indices)
            )
            patches_local.append(arr[patch_slices])

        return patches_local

    all_patches = []

    # Extract from original
    all_patches.extend(_extract_from_single_array(data))

    # Extract from transformed versions
    if transforms is not None:
        for transform in transforms:
            transformed = transform(data)
            all_patches.extend(_extract_from_single_array(transformed))

    return all_patches

# %% ../nbs/01_data.ipynb #337a703a
def save_patches_grid(data_paths,                   # Path to folder or list of paths to data files (n-dimensional data).
                      gt_paths,                     # Path to folder or list of paths to ground truth (gt) files (n-dimensional data).
                      output_folder,                # Path to the folder where the HDF5 files will be saved.
                      patch_size,                   # tuple of integers defining the size of the patches.
                      overlap,                       # float (between 0 and 1) defining the overlap between patches.
                      use_parent_folder = False,     # If True, use the parent folder name of the input files for naming the output HDF5 files.
                      threshold=None,                # If provided, patches with a mean value below this threshold will be discarded.
                      squeeze_input=True,            # If True, squeeze the input data to remove single-dimensional entries. 
                      squeeze_patches=False,         # If True, squeeze the patches to remove single-dimensional entries.
                      csv_output=True,               # If True, a CSV file listing all patch paths is created.
                      split_dataset=True,            # Split dataset into train and test CSV files (e.g., 0.8 for 80% train).
                      tfms_before: List|None = None,      # List of transforms to apply before extracting patches.
                      tfms_after: List|None = None,       # List of transforms to apply after extracting patches.
                      **kwargs,                      # Additional keyword arguments for splitting the dataset (see split_dataframe function)
                      ):
    """
    Loads n-dimensional data from data_paths and gt_paths, generates patches, and saves them into individual HDF5 files.
    Each HDF5 file will have datasets with the structure X/patch_idx and y/patch_idx.
    
    Parameters:
    - data_paths: Can be a folder path (string) or a list of file paths to data files
    - gt_paths: Can be a folder path (string) or a list of file paths to ground truth files
    """
    
    # Ensure output folder exists
    if output_folder is not None or output_folder != '':
        os.makedirs(output_folder, exist_ok=True)
        use_full_path = False
    else:
        use_full_path = True
    
    # Convert folder paths to lists of file paths if necessary
    if isinstance(data_paths, str):         # It's a folder path
        data_files = sorted([os.path.join(data_paths, f) 
                           for f in os.listdir(data_paths) 
                           if f.endswith(('.npy', '.npz', '.png', '.tif', '.tiff'))])
    else:        # It's already a list of paths
        data_files = sorted(data_paths)
    
    if isinstance(gt_paths, str):        # It's a folder path
        gt_files = sorted([os.path.join(gt_paths, f) 
                         for f in os.listdir(gt_paths) 
                         if f.endswith(('.npy', '.npz', '.png', '.tif', '.tiff'))])
    else:        # It's already a list of paths
        gt_files = sorted(gt_paths)

    # Ensure the folders contain the same number of files
    if len(data_files) != len(gt_files):
        raise ValueError("The number of files in data_paths and gt_paths must be the same.")
    
    # Prepare CSV records list
    csv_records = []

    # Loop through the files
    for data_file_path, gt_file_path in tqdm(zip(data_files, gt_files), total=len(data_files), desc="Processing files"):
        # Extract filename for HDF5 output
        if use_full_path:
            data_file_name = os.path.splitext(data_file_path)[0]
        elif use_parent_folder: 
            data_file_name = os.path.splitext(os.path.join(os.path.basename(os.path.dirname(data_file_path)), os.path.basename(data_file_path)))[0]
        else:   
            data_file_name = os.path.splitext(os.path.basename(data_file_path))[0]
        
        # Load the images
        data = image_reader(data_file_path, dtype=np.array)
        gt = image_reader(gt_file_path, dtype=np.array)
        
        if squeeze_input:
            data = np.squeeze(data)
            gt = np.squeeze(gt)
        
        gt_patch_size = patch_size  # Assuming the same patch size for gt, can be modified to accept a different one

        # Apply transforms before extracting patches
        if tfms_before is not None:
            data, gt = apply_transforms((data, gt), tfms_before)

        # Check if data and gt have the same shape, if not, attempt to align spatial dimensions
        if data.shape != gt.shape:
            if data.shape[-2:] != gt.shape[-2:]:
                raise ValueError(f"Spatial dimension mismatch between {os.path.basename(data_file_path)} and {os.path.basename(gt_file_path)}: {data.shape} vs {gt.shape}")
            gt_patch_size = patch_size[-2:]  # Use only spatial dimensions for gt patches
        
        # Extract patches from both datasets
        data_patches_nd = extract_patches(data, patch_size, overlap)
        gt_patches_nd = extract_patches(gt, gt_patch_size, overlap)
        
        if squeeze_patches:
            data_patches_nd = np.squeeze(data_patches_nd)
            gt_patches_nd = np.squeeze(gt_patches_nd)
        
        # Create a new HDF5 file for this pair of files
        hdf5_filename = os.path.join(output_folder, f"{os.path.splitext(data_file_name)[0]}.h5")
        
        with h5py.File(hdf5_filename, 'w') as hf:
            patch_counter = 0  # Counter to number the valid patches
            
            # Store each patch in a separate dataset
            for data_patch, gt_patch in tqdm(zip(data_patches_nd, gt_patches_nd), 
                                             total=len(data_patches_nd), 
                                             desc=f"Saving patches for {data_file_name}", 
                                             leave=False):
                # Calculate the mean of the patch and discard if below threshold (if provided)
                if threshold is not None and np.mean(data_patch) < threshold:
                    continue  # Skip this patch
                
                # Apply transforms after extracting patches
                if tfms_after is not None:
                    data_patch, gt_patch = apply_transforms((data_patch, gt_patch), tfms_after)
                
                hf.create_dataset(f'X/{patch_counter}', data=data_patch)
                hf.create_dataset(f'y/{patch_counter}', data=gt_patch)
                
                # Append patch paths to CSV records
                csv_records.append({
                    "path_signal": f"{hdf5_filename}/X/{patch_counter}",
                    "path_target": f"{hdf5_filename}/y/{patch_counter}"
                })
                
                patch_counter += 1  # Increment the patch counter only for valid patches
    
    # Save the paths to a CSV file if csv_output is True
    if csv_output:
        csv_df = pd.DataFrame(csv_records)
        
        if split_dataset:
            # Split data into train and test sets
                        
            ops = {
                'train_fraction': kwargs.get('train_fraction', 0.7),
                'valid_fraction': kwargs.get('valid_fraction', 0.1),
                'split_column': kwargs.get('split_column', None),
                'stratify': kwargs.get('stratify', False),  
                'add_is_valid': kwargs.get('add_is_valid', True),
                'train_path': kwargs.get('train_path', "patches_train.csv"),
                'test_path': kwargs.get('test_path', "patches_test.csv"),
                'valid_path': kwargs.get('valid_path', "patches_valid.csv"),
                'data_save_path': kwargs.get('data_save_path', output_folder)
            }
            
            split_dataframe(csv_df, **ops)
        
        else:
            # Save a single CSV file
            csv_path = os.path.join(output_folder, "all_patches.csv")
            csv_df.to_csv(csv_path, index=False)
            print(f"CSV file saved to: {csv_path}")


# %% ../nbs/01_data.ipynb #d5e46c28
def extract_random_patches(data_tuple, # tuple of numpy arrays (input data, ground truth data).
                           patch_size, # tuple of integers defining the size of the patches in each dimension.
                           num_patches, # number of random patches to extract.
                           ):
    """
    Extracts a specified number of random n-dimensional patches from the input data and ground truth data.
    
    Returns:
    - A tuple of lists containing randomly cropped patches as numpy arrays (input_patches, gt_patches).
    """
    input_data, gt_data = data_tuple
    input_shape = input_data.shape
    gt_shape = gt_data.shape
    
    if input_shape != gt_shape:
        raise ValueError("Input data and ground truth data must have the same shape.")
    
    ndim = len(input_shape)
    
    # Ensure patch size fits within the data dimensions
    for dim in range(ndim):
        if patch_size[dim] > input_shape[dim]:
            raise ValueError(f"Patch size {patch_size[dim]} exceeds data dimension {input_shape[dim]} in dimension {dim}")
    
    input_patches = []
    gt_patches = []
    
    for _ in range(num_patches):
        # Randomly select the starting point for each dimension
        start_coords = [random.randint(0, input_shape[dim] - patch_size[dim]) for dim in range(ndim)]
        
        # Create slices for the selected patch
        patch_slices = tuple(slice(start_coords[dim], start_coords[dim] + patch_size[dim]) for dim in range(ndim))
        
        # Extract the patch and add to the lists
        input_patches.append(input_data[patch_slices])
        gt_patches.append(gt_data[patch_slices])
    
    return input_patches, gt_patches


